INSERT INTO `topics` VALUES (1,'Chào hỏi hằng ngày','Những câu chào người Nhật dùng hàng chục lần mỗi ngày. Học xong chủ đề này bạn đã có thể chào hỏi, cảm ơn, xin lỗi và tạm biệt đúng hoàn cảnh — phần được đánh giá cao nhất khi giao tiếp với người Nhật.',1,'2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(2,'Giới thiệu bản thân','Mẫu câu N は N です — bộ khung câu đầu tiên và quan trọng nhất của tiếng Nhật. Hết chủ đề này bạn tự giới thiệu được tên, quốc tịch, nghề nghiệp và đặt câu hỏi ngược lại cho người đối diện.',2,'2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(3,'Số đếm, tuổi và giá tiền','Con số là thứ bạn dùng ngay ngày đầu đặt chân tới Nhật: xem giá, trả tiền, nói tuổi, đọc số điện thoại. Chủ đề này đi từ số 1 đến hàng vạn, kèm các đơn vị đếm hay dùng nhất.',3,'2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(4,'Đồ vật quanh ta','Bộ chỉ định これ・それ・あれ và cách hỏi tên đồ vật. Đây là chủ đề giúp bạn tự học từ vựng suốt đời: chỉ vào bất cứ thứ gì và hỏi これはなんですか.',4,'2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(5,'Địa điểm và vị trí','Hỏi đường, chỉ chỗ, nói vật gì nằm ở đâu. Chủ đề này gồm cả cặp động từ あります và います — điểm ngữ pháp mà người mới học hay dùng sai nhất.',5,'2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(6,'Thời gian và lịch','Xem giờ, hẹn giờ, nói thứ ngày tháng. Người Nhật cực kỳ đúng giờ nên đây là chủ đề bắt buộc phải chắc trước khi đi làm hay đi học ở Nhật.',6,'2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(7,'Động từ và sinh hoạt hằng ngày','Động từ thể ます — thể lịch sự chuẩn mực để nói chuyện với bất kỳ ai. Chủ đề này cũng dạy 4 trợ từ quan trọng nhất khi ghép câu có động từ: を, へ, で, に.',7,'2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(8,'Ăn uống và nhà hàng','Từ vựng món ăn, đồ uống và trọn bộ mẫu câu để gọi món, hỏi giá, khen ngon. Chủ đề thực dụng nhất — dùng được ngay trong bữa ăn đầu tiên ở Nhật.',8,'2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(9,'Gia đình và con người','Tiếng Nhật có 2 bộ từ gia đình riêng biệt: một bộ dùng khi nói về nhà mình, một bộ dùng khi nói về nhà người khác. Dùng nhầm bộ là lỗi lễ nghi khá nặng.',9,'2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(10,'Tính từ và miêu tả','Tiếng Nhật có 2 loại tính từ chia khác nhau hoàn toàn: tính từ đuôi い và tính từ đuôi な. Phân biệt được 2 loại này là bạn đã nắm gần trọn ngữ pháp N5.',10,'2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(11,'Mua sắm ở cửa hàng','Chủ đề đưa bạn đi hết một lần mua sắm: biết tên các loại cửa hàng, gọi tên món đồ mình cần, hỏi giá, xin cỡ khác và trả tiền. Đây là tình huống người nước ngoài ở Nhật phải dùng tiếng Nhật nhiều nhất trong tuần đầu tiên.',11,'2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(12,'Đi lại và phương tiện','Tàu điện là mạch máu của đời sống Nhật Bản. Chủ đề này dạy bạn gọi tên phương tiện, mua vé, tìm đúng lối ra, hỏi đường khi lạc và hỏi đi mất bao lâu — đủ để tự đi lại một mình mà không cần ai dẫn.',12,'2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(13,'Sở thích và ngày nghỉ','Câu hỏi しゅみはなんですか (sở thích của bạn là gì?) gần như chắc chắn xuất hiện trong mọi cuộc làm quen với người Nhật. Chủ đề này cho bạn đủ vốn từ để trả lời, để nói thích hay không thích, giỏi hay kém, và kể mình làm gì vào cuối tuần.',13,'2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(14,'Sức khoẻ và cơ thể','Chủ đề không ai muốn dùng nhưng lúc cần thì không thay thế được: gọi tên bộ phận cơ thể, nói đúng chỗ đang đau, mua thuốc và hiểu câu bác sĩ hỏi. Học trước lúc khoẻ để lúc ốm còn nói được.',14,'2026-08-26 17:38:13','2026-08-26 17:38:13',NULL);
/*!40000 ALTER TABLE `topics` ENABLE KEYS */;
UNLOCK TABLES;

