CREATE TABLE `lessons` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `topic_id` bigint NOT NULL DEFAULT '1',
  `jlpt_level` enum('N5','N4','N3','N2','N1') NOT NULL,
  `title` varchar(255) NOT NULL,
  `order_index` int DEFAULT NULL COMMENT 'NULL cho JUMP_TEST (vẽ ở Header, không nằm trên đường uốn lượn)',
  `lesson_type` enum('NORMAL','TIMED_REVIEW','TOPIC_REVIEW','JUMP_TEST') NOT NULL,
  `config_json` json DEFAULT NULL COMMENT 'Lưu luật chơi riêng: time_limit_sec, entry_cost, star_thresholds',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_lesson_topic` (`topic_id`),
  CONSTRAINT `fk_lesson_topic` FOREIGN KEY (`topic_id`) REFERENCES `topics` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=133 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
