INSERT INTO `lessons` VALUES (1,1,'N5','Bài 1: Chào theo buổi trong ngày',1,'NORMAL','{\"expReward\": 20, \"description\": \"Tiếng Nhật không có một câu chào dùng chung cho cả ngày như Xin chào của tiếng Việt. Chào sai buổi nghe rất kỳ, nên hãy nhớ mốc thời gian: sáng đến ~10h, trưa chiều đến ~18h, sau đó là buổi tối.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(2,1,'N5','Bài 2: Cảm ơn và xin lỗi',2,'NORMAL','{\"expReward\": 20, \"description\": \"すみません là từ vạn năng bậc nhất tiếng Nhật: vừa là xin lỗi, vừa là làm phiền chút để gọi người khác, vừa có thể thay cho cảm ơn khi ai đó giúp mình. Còn ごめんなさい chỉ dùng để xin lỗi khi mình có lỗi thật.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(3,1,'N5','Bài 3: Lần đầu gặp mặt',3,'NORMAL','{\"expReward\": 20, \"description\": \"Bộ đôi はじめまして và よろしくおねがいします là nghi thức bắt buộc khi làm quen người Nhật, luôn đi kèm một cái cúi đầu nhẹ. Câu thứ hai không dịch sát được sang tiếng Việt, nghĩa gần nhất là mong được bạn giúp đỡ từ nay về sau.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(4,1,'N5','Bài 4: Tạm biệt',4,'NORMAL','{\"expReward\": 20, \"description\": \"さようなら nghe khá nặng nề, hàm ý lâu rồi mới gặp lại — người Nhật ít dùng với bạn bè hằng ngày. Đi làm, đi học thì dùng またあした hoặc しつれいします.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(5,1,'N5','Bài 5: Chào khi ra khỏi nhà và về nhà',5,'NORMAL','{\"expReward\": 20, \"description\": \"4 câu này đi thành 2 cặp hỏi - đáp cố định trong mọi gia đình Nhật: người đi nói いってきます, người ở nhà đáp いってらっしゃい; lúc về thì ただいま và おかえりなさい. Bạn sẽ nghe chúng trong mọi bộ phim, anime Nhật.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(6,1,'N5','Bài 6: Chào trong bữa ăn và nơi làm việc',6,'NORMAL','{\"expReward\": 20, \"description\": \"いただきます nói trước khi ăn (kể cả khi ăn một mình) để cảm ơn thức ăn, ごちそうさまでした nói sau khi ăn xong. おつかれさまです là câu chào phổ biến nhất trong công ty Nhật, dùng được cả khi gặp lẫn khi chia tay đồng nghiệp.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(7,1,'N5','Ôn tập tốc độ: Chào hỏi hằng ngày',NULL,'TIMED_REVIEW','{\"expReward\": 30, \"description\": \"\", \"replayExpRatio\": 0.3, \"starThresholds\": [90, 150], \"entryCostEnergy\": 5, \"questionsPerSession\": 12}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(8,1,'N5','Thi vượt: Chào hỏi hằng ngày',NULL,'JUMP_TEST','{\"expReward\": 80, \"description\": \"\", \"entryCostEnergy\": 15, \"questionsPerSession\": 15}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(9,2,'N5','Bài 1: Tôi là… (わたしは〜です)',1,'NORMAL','{\"expReward\": 20, \"description\": \"Cấu trúc: A は B です = A thì/là B. は ở đây là trợ từ chủ đề, đọc là WA chứ không đọc HA. です đứng cuối câu tạo sắc thái lịch sự — người Nhật gần như luôn dùng です khi nói với người mới quen.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(10,2,'N5','Bài 2: Quốc gia và quốc tịch',2,'NORMAL','{\"expReward\": 20, \"description\": \"Quy tắc cực gọn: tên nước + じん (người) = quốc tịch; tên nước + ご = ngôn ngữ. にほん + じん = にほんじん (người Nhật), にほん + ご = にほんご (tiếng Nhật). Riêng tiếng Anh là えいご, không phải アメリカご.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(11,2,'N5','Bài 3: Nghề nghiệp',3,'NORMAL','{\"expReward\": 20, \"description\": \"Người Nhật rất hay hỏi nghề nghiệp khi mới quen. Lưu ý せんせい chỉ dùng để gọi người khác (thầy cô, bác sĩ, luật sư), không bao giờ tự xưng わたしはせんせいです với người ngoài — sẽ nghe như đang tự đề cao mình.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(12,2,'N5','Bài 4: Câu hỏi với か và cách trả lời',4,'NORMAL','{\"expReward\": 20, \"description\": \"Tiếng Nhật không đảo trật tự từ để hỏi như tiếng Anh. Chỉ cần thêm か vào cuối câu là thành câu hỏi, giữ nguyên mọi thứ còn lại: がくせいです → がくせいですか. Trong văn viết thường không cần dấu chấm hỏi.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(13,2,'N5','Bài 5: Câu phủ định じゃありません',5,'NORMAL','{\"expReward\": 20, \"description\": \"Để phủ định, thay です bằng じゃありません: がくせいです → がくせいじゃありません (không phải sinh viên). Dạng trang trọng hơn là ではありません, thường gặp trong văn viết và thông báo chính thức.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(14,2,'N5','Bài 6: Trợ từ の (của)',6,'NORMAL','{\"expReward\": 20, \"description\": \"の nối 2 danh từ theo thứ tự NGƯỢC với tiếng Việt: わたしのなまえ = tên CỦA TÔI (sở hữu đứng trước). Cũng dùng để chỉ nơi công tác hay lĩnh vực: にほんごのせんせい = giáo viên tiếng Nhật.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(15,2,'N5','Ôn tập tốc độ: Giới thiệu bản thân',NULL,'TIMED_REVIEW','{\"expReward\": 30, \"description\": \"\", \"replayExpRatio\": 0.3, \"starThresholds\": [90, 150], \"entryCostEnergy\": 5, \"questionsPerSession\": 12}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(16,2,'N5','Thi vượt: Giới thiệu bản thân',NULL,'JUMP_TEST','{\"expReward\": 80, \"description\": \"\", \"entryCostEnergy\": 15, \"questionsPerSession\": 15}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(17,3,'N5','Bài 1: Số từ 1 đến 10',1,'NORMAL','{\"expReward\": 20, \"description\": \"4 và 7 có 2 cách đọc: よん/し và なな/しち. Người Nhật thường dùng よん và なな vì し trùng âm với từ chết (死) — kiêng kỵ giống số 13 của phương Tây.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(18,3,'N5','Bài 2: Số từ 11 đến 100',2,'NORMAL','{\"expReward\": 20, \"description\": \"Cách ghép số của tiếng Nhật rất logic, không có từ bất quy tắc như eleven, twelve của tiếng Anh: 11 = 10+1 = じゅういち, 20 = 2×10 = にじゅう, 35 = 3×10+5 = さんじゅうご. Nắm 10 số đầu là đọc được tới 99.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(19,3,'N5','Bài 3: Số lớn — trăm, nghìn, vạn',3,'NORMAL','{\"expReward\": 20, \"description\": \"Tiếng Nhật đếm theo đơn vị VẠN (まん = 10.000) chứ không theo nghìn như tiếng Việt. 100.000 đồng người Nhật đọc là じゅうまん (10 vạn). Đây là chỗ người Việt hay nhầm nhất khi nghe giá tiền.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(20,3,'N5','Bài 4: Tuổi và số điện thoại',4,'NORMAL','{\"expReward\": 20, \"description\": \"Tuổi dùng đuôi さい. Có 3 trường hợp đọc bất quy tắc phải học thuộc: 1 tuổi いっさい, 8 tuổi はっさい, 20 tuổi はたち (không phải にじゅっさい). Đọc số điện thoại thì đọc rời từng số, dấu gạch ngang đọc là の.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(21,3,'N5','Bài 5: Hỏi giá và mua hàng',5,'NORMAL','{\"expReward\": 20, \"description\": \"いくらですか là câu bạn sẽ dùng nhiều nhất khi đi mua sắm ở Nhật. Đồng yên viết là えん (円). Khi muốn mua, chỉ cần chỉ vào món đồ và nói これをください.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(22,3,'N5','Bài 6: Đơn vị đếm đồ vật',6,'NORMAL','{\"expReward\": 20, \"description\": \"Tiếng Nhật không đếm suông mà phải kèm đơn vị theo hình dạng vật: まい cho vật mỏng dẹt (giấy, áo, vé), ほん cho vật dài (bút, chai, ô), にん cho người, còn つ là đơn vị vạn năng dùng khi bạn quên mất đơn vị đúng.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(23,3,'N5','Ôn tập: Số đếm, tuổi và giá tiền',7,'TOPIC_REVIEW','{\"expReward\": 30, \"description\": \"\", \"replayExpRatio\": 0.3, \"starThresholds\": [90, 150], \"entryCostEnergy\": 5, \"questionsPerSession\": 12}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(24,3,'N5','Ôn tập tốc độ: Số đếm, tuổi và giá tiền',NULL,'TIMED_REVIEW','{\"expReward\": 30, \"description\": \"\", \"replayExpRatio\": 0.3, \"starThresholds\": [90, 150], \"entryCostEnergy\": 5, \"questionsPerSession\": 12}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(25,3,'N5','Thi vượt: Số đếm, tuổi và giá tiền',NULL,'JUMP_TEST','{\"expReward\": 80, \"description\": \"\", \"entryCostEnergy\": 15, \"questionsPerSession\": 15}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(26,4,'N5','Bài 1: これ・それ・あれ・どれ',1,'NORMAL','{\"expReward\": 20, \"description\": \"3 từ chỉ định chia theo khoảng cách: これ = cái này (gần người nói), それ = cái đó (gần người nghe), あれ = cái kia (xa cả hai). どれ = cái nào. Tiếng Việt chỉ có 2 mức nên hãy chú ý mức giữa それ.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(27,4,'N5','Bài 2: Đồ dùng học tập',2,'NORMAL','{\"expReward\": 20, \"description\": \"Từ vựng trong cặp sách. Để ý ノート và ペン viết bằng Katakana vì là từ mượn tiếng Anh, còn ほん và えんぴつ là từ thuần Nhật nên viết Hiragana.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(28,4,'N5','Bài 3: Đồ dùng hằng ngày',3,'NORMAL','{\"expReward\": 20, \"description\": \"Những vật bạn mang theo mỗi khi ra khỏi nhà. かさ (ô) là vật cực kỳ quan trọng ở Nhật vì mưa rất thất thường — cửa hàng tiện lợi nào cũng bán.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(29,4,'N5','Bài 4: この・その・あの + danh từ',4,'NORMAL','{\"expReward\": 20, \"description\": \"Khác biệt quan trọng: これ đứng MỘT MÌNH (cái này), còn この phải có danh từ đi kèm ngay sau (この本 = quyển sách này). Nói このです là sai ngữ pháp, và nói これ本 cũng sai.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(30,4,'N5','Bài 5: Đồ này của ai?',5,'NORMAL','{\"expReward\": 20, \"description\": \"Khi đã rõ đang nói về vật gì, người Nhật lược bỏ luôn danh từ sau の: わたしのです = (cái này) của tôi. Cách nói tỉnh lược này rất phổ biến trong hội thoại đời thường.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(31,4,'N5','Bài 6: Hỏi tên đồ vật',6,'NORMAL','{\"expReward\": 20, \"description\": \"これはなんですか là chiếc chìa khóa để tự học từ vựng khi ở Nhật: chỉ vào vật lạ bất kỳ và hỏi. Khi trả lời sai, người Nhật lịch sự sẽ nói ちがいます chứ ít khi nói thẳng là bạn sai.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(32,4,'N5','Ôn tập: Đồ vật quanh ta',7,'TOPIC_REVIEW','{\"expReward\": 30, \"description\": \"\", \"replayExpRatio\": 0.3, \"starThresholds\": [90, 150], \"entryCostEnergy\": 5, \"questionsPerSession\": 12}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(33,4,'N5','Ôn tập tốc độ: Đồ vật quanh ta',NULL,'TIMED_REVIEW','{\"expReward\": 30, \"description\": \"\", \"replayExpRatio\": 0.3, \"starThresholds\": [90, 150], \"entryCostEnergy\": 5, \"questionsPerSession\": 12}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(34,4,'N5','Thi vượt: Đồ vật quanh ta',NULL,'JUMP_TEST','{\"expReward\": 80, \"description\": \"\", \"entryCostEnergy\": 15, \"questionsPerSession\": 15}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(35,5,'N5','Bài 1: ここ・そこ・あそこ・どこ',1,'NORMAL','{\"expReward\": 20, \"description\": \"Giống bộ これ・それ・あれ nhưng dùng cho ĐỊA ĐIỂM: ここ = chỗ này, そこ = chỗ đó, あそこ = chỗ kia, どこ = chỗ nào. Nhận ra quy luật ko-so-a-do rồi thì bạn học các bộ từ chỉ định còn lại rất nhanh.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(36,5,'N5','Bài 2: Địa điểm trong thành phố',2,'NORMAL','{\"expReward\": 20, \"description\": \"Những nơi bạn cần tìm nhất khi mới sang Nhật. コンビニ (cửa hàng tiện lợi) là từ rút gọn của convenience store — người Nhật rất hay rút gọn từ mượn dài.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(37,5,'N5','Bài 3: Các phòng trong nhà',3,'NORMAL','{\"expReward\": 20, \"description\": \"Nhà Nhật tách riêng おふろ (phòng tắm) và トイレ (nhà vệ sinh) thành 2 phòng khác nhau — hỏi nhầm phòng là chuyện thường gặp của người nước ngoài.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(38,5,'N5','Bài 4: あります và います',4,'NORMAL','{\"expReward\": 20, \"description\": \"Cùng nghĩa là CÓ nhưng chia theo sự sống: います dùng cho người và động vật (vật biết tự di chuyển), あります dùng cho đồ vật và cây cối. Nói ねこがあります là sai — mèo phải dùng います.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(39,5,'N5','Bài 5: Từ chỉ vị trí',5,'NORMAL','{\"expReward\": 20, \"description\": \"Cấu trúc: A の + từ vị trí + に. Ví dụ つくえのうえに = ở trên bàn. Thứ tự ngược với tiếng Việt: vật mốc đứng trước, vị trí đứng sau.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(40,5,'N5','Bài 6: Hỏi đường',6,'NORMAL','{\"expReward\": 20, \"description\": \"Công thức hỏi đường an toàn nhất: mở đầu bằng すみません để gây chú ý, rồi hỏi 〜はどこですか. Kết thúc luôn nhớ nói ありがとうございます — người Nhật rất coi trọng lời cảm ơn sau khi được giúp.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(41,5,'N5','Ôn tập: Địa điểm và vị trí',7,'TOPIC_REVIEW','{\"expReward\": 30, \"description\": \"\", \"replayExpRatio\": 0.3, \"starThresholds\": [90, 150], \"entryCostEnergy\": 5, \"questionsPerSession\": 12}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(42,5,'N5','Ôn tập tốc độ: Địa điểm và vị trí',NULL,'TIMED_REVIEW','{\"expReward\": 30, \"description\": \"\", \"replayExpRatio\": 0.3, \"starThresholds\": [90, 150], \"entryCostEnergy\": 5, \"questionsPerSession\": 12}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(43,5,'N5','Thi vượt: Địa điểm và vị trí',NULL,'JUMP_TEST','{\"expReward\": 80, \"description\": \"\", \"entryCostEnergy\": 15, \"questionsPerSession\": 15}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(44,6,'N5','Bài 1: Xem giờ (〜じ)',1,'NORMAL','{\"expReward\": 20, \"description\": \"Ghép số + じ là ra giờ. Nhưng có 3 giờ đọc bất quy tắc phải học thuộc lòng: 4 giờ là よじ (không phải よんじ), 7 giờ là しちじ, 9 giờ là くじ (không phải きゅうじ).\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(45,6,'N5','Bài 2: Phút và giờ rưỡi',2,'NORMAL','{\"expReward\": 20, \"description\": \"Đuôi phút biến âm theo số đứng trước: いっぷん, にふん, さんぷん, よんぷん, ごふん. Quy luật chung là sau các số 1, 3, 6, 8, 10 thì đọc ぷん. Giờ rưỡi dùng はん cho gọn: しちじはん = 7 giờ rưỡi.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(46,6,'N5','Bài 3: Buổi trong ngày, hôm qua và ngày mai',3,'NORMAL','{\"expReward\": 20, \"description\": \"Nhóm từ chỉ mốc thời gian tương đối. Chú ý あさ (buổi sáng) khác với あした (ngày mai) chỉ 1 chữ — người mới học rất hay nhầm 2 từ này.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(47,6,'N5','Bài 4: Thứ trong tuần',4,'NORMAL','{\"expReward\": 20, \"description\": \"Tên các thứ đặt theo ngũ hành và thiên thể: nguyệt (trăng), hỏa, thủy, mộc, kim, thổ, nhật (mặt trời). Đều kết thúc bằng ようび nên chỉ cần nhớ chữ đầu.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(48,6,'N5','Bài 5: Tháng và ngày',5,'NORMAL','{\"expReward\": 20, \"description\": \"Tháng rất dễ: số + がつ (いちがつ = tháng 1). Nhưng ngày mùng 1 đến mùng 10 đọc hoàn toàn bất quy tắc (ついたち, ふつか, みっか…) — đây là phần khó nhằn nhất của lịch tiếng Nhật, cần luyện đi luyện lại.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(49,6,'N5','Bài 6: Từ… đến… (〜から〜まで)',6,'NORMAL','{\"expReward\": 20, \"description\": \"から = từ (điểm bắt đầu), まで = đến (điểm kết thúc). Dùng được cho cả thời gian lẫn địa điểm: くじからごじまで (từ 9 giờ đến 5 giờ), とうきょうからおおさかまで (từ Tokyo đến Osaka).\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(50,6,'N5','Ôn tập: Thời gian và lịch',7,'TOPIC_REVIEW','{\"expReward\": 30, \"description\": \"\", \"replayExpRatio\": 0.3, \"starThresholds\": [90, 150], \"entryCostEnergy\": 5, \"questionsPerSession\": 12}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(51,6,'N5','Ôn tập tốc độ: Thời gian và lịch',NULL,'TIMED_REVIEW','{\"expReward\": 30, \"description\": \"\", \"replayExpRatio\": 0.3, \"starThresholds\": [90, 150], \"entryCostEnergy\": 5, \"questionsPerSession\": 12}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(52,6,'N5','Thi vượt: Thời gian và lịch',NULL,'JUMP_TEST','{\"expReward\": 80, \"description\": \"\", \"entryCostEnergy\": 15, \"questionsPerSession\": 15}','2026-08-26 17:38:13','2026-08-26 17:38:13',NULL),(53,7,'N5','Bài 1: Động từ đầu tiên',1,'NORMAL','{\"expReward\": 20, \"description\": \"Điểm khác biệt lớn nhất với tiếng Việt: động từ tiếng Nhật luôn đứng CUỐI CÂU. Tôi ăn cơm trong tiếng Nhật là Tôi cơm ăn. Đuôi ます làm câu thành lịch sự và mang nghĩa hiện tại hoặc tương lai.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(54,7,'N5','Bài 2: Đi, đến, về nhà',2,'NORMAL','{\"expReward\": 20, \"description\": \"Bộ 3 động từ di chuyển đi kèm trợ từ へ (chỉ hướng, viết là へ nhưng đọc là E). Cấu trúc: [nơi đến] へ いきます. Có thể thay へ bằng に, nghĩa gần như nhau.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(55,7,'N5','Bài 3: Trợ từ を (tân ngữ)',3,'NORMAL','{\"expReward\": 20, \"description\": \"を đánh dấu đối tượng chịu tác động của động từ. Chữ を chỉ dùng đúng cho việc này, không bao giờ dùng để viết từ, và đọc là O chứ không phải WO. Cấu trúc: [vật] を [động từ].\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(56,7,'N5','Bài 4: Trợ từ で (nơi diễn ra hành động)',4,'NORMAL','{\"expReward\": 20, \"description\": \"Phân biệt cực quan trọng: に chỉ nơi TỒN TẠI (へやにいます = ở trong phòng), còn で chỉ nơi DIỄN RA HÀNH ĐỘNG (へやでべんきょうします = học trong phòng). Dùng nhầm 2 trợ từ này là lỗi kinh điển của người mới.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(57,7,'N5','Bài 5: Quá khứ và phủ định',5,'NORMAL','{\"expReward\": 20, \"description\": \"Chia động từ tiếng Nhật cực kỳ đều đặn, chỉ cần đổi đuôi ます: hiện tại ます → phủ định ません → quá khứ ました → quá khứ phủ định ませんでした. Không đổi theo ngôi hay số nhiều như tiếng Anh.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(58,7,'N5','Bài 6: Trợ từ に (mốc thời gian)',6,'NORMAL','{\"expReward\": 20, \"description\": \"に đứng sau mốc thời gian CÓ CON SỐ: しちじにおきます (dậy lúc 7 giờ). Nhưng các từ như きょう, あした, まいにち thì KHÔNG dùng に — nói あしたにいきます là sai, phải nói あしたいきます.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(59,7,'N5','Bài 7: Kể về một ngày của bạn',7,'NORMAL','{\"expReward\": 20, \"description\": \"Bài tổng hợp: ghép tất cả trợ từ và động từ đã học thành một đoạn kể liền mạch. Trật tự câu chuẩn của tiếng Nhật là: [Thời gian] [Nơi chốn] [Tân ngữ] [Động từ].\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(60,7,'N5','Ôn tập: Động từ và sinh hoạt hằng ngày',8,'TOPIC_REVIEW','{\"expReward\": 30, \"description\": \"\", \"replayExpRatio\": 0.3, \"starThresholds\": [90, 150], \"entryCostEnergy\": 5, \"questionsPerSession\": 12}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(61,7,'N5','Ôn tập tốc độ: Động từ và sinh hoạt hằng ngày',NULL,'TIMED_REVIEW','{\"expReward\": 30, \"description\": \"\", \"replayExpRatio\": 0.3, \"starThresholds\": [90, 150], \"entryCostEnergy\": 5, \"questionsPerSession\": 12}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(62,7,'N5','Thi vượt: Động từ và sinh hoạt hằng ngày',NULL,'JUMP_TEST','{\"expReward\": 80, \"description\": \"\", \"entryCostEnergy\": 15, \"questionsPerSession\": 15}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(63,8,'N5','Bài 1: Thức ăn cơ bản',1,'NORMAL','{\"expReward\": 20, \"description\": \"Nhóm từ nền tảng trong mọi thực đơn. ごはん vừa có nghĩa là cơm trắng, vừa có nghĩa là bữa ăn nói chung — tuỳ ngữ cảnh mà hiểu.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(64,8,'N5','Bài 2: Đồ uống',2,'NORMAL','{\"expReward\": 20, \"description\": \"Chữ お ở đầu おちゃ, おさけ là tiếp đầu ngữ lịch sự — bỏ đi vẫn đúng nghĩa nhưng nghe kém trang trọng. Người Nhật hầu như luôn nói kèm お cho 2 từ này.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(65,8,'N5','Bài 3: Món ăn Nhật Bản',3,'NORMAL','{\"expReward\": 20, \"description\": \"Những món bạn sẽ thấy ở mọi nhà hàng Nhật. おにぎり là món ăn nhanh quốc dân, bán ở mọi cửa hàng tiện lợi với giá chỉ hơn 100 yên.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(66,8,'N5','Bài 4: Gọi món trong nhà hàng',4,'NORMAL','{\"expReward\": 20, \"description\": \"2 cách gọi món: 〜をください (cho tôi…) dùng khi chỉ vào món cụ thể, còn 〜をおねがいします lịch sự hơn một bậc, dùng được cả khi nhờ vả việc khác.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(67,8,'N5','Bài 5: Nói về mùi vị',5,'NORMAL','{\"expReward\": 20, \"description\": \"おいしい (ngon) là lời khen được dùng nhiều nhất trên bàn ăn Nhật. Ngược lại まずい (dở) nghe khá thô lỗ nếu nói trước mặt người nấu — người Nhật thường tránh né bằng cách nói ちょっと… (hơi… ).\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(68,8,'N5','Bài 6: Hội thoại trong nhà hàng',6,'NORMAL','{\"expReward\": 20, \"description\": \"Ghép toàn bộ mẫu câu đã học thành một cuộc hội thoại hoàn chỉnh từ lúc bước vào đến lúc trả tiền. いらっしゃいませ là câu nhân viên chào khách — bạn không cần đáp lại, chỉ cần gật đầu.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(69,8,'N5','Ôn tập: Ăn uống và nhà hàng',7,'TOPIC_REVIEW','{\"expReward\": 30, \"description\": \"\", \"replayExpRatio\": 0.3, \"starThresholds\": [90, 150], \"entryCostEnergy\": 5, \"questionsPerSession\": 12}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(70,8,'N5','Ôn tập tốc độ: Ăn uống và nhà hàng',NULL,'TIMED_REVIEW','{\"expReward\": 30, \"description\": \"\", \"replayExpRatio\": 0.3, \"starThresholds\": [90, 150], \"entryCostEnergy\": 5, \"questionsPerSession\": 12}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(71,8,'N5','Thi vượt: Ăn uống và nhà hàng',NULL,'JUMP_TEST','{\"expReward\": 80, \"description\": \"\", \"entryCostEnergy\": 15, \"questionsPerSession\": 15}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(72,9,'N5','Bài 1: Gia đình của tôi',1,'NORMAL','{\"expReward\": 20, \"description\": \"Bộ từ KHIÊM NHƯỜNG, chỉ dùng khi nói về người nhà MÌNH với người ngoài. Người Nhật hạ thấp gia đình mình để đề cao người đối diện — nguyên tắc giao tiếp quan trọng nhất của xã hội Nhật.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(73,9,'N5','Bài 2: Gia đình của người khác',2,'NORMAL','{\"expReward\": 20, \"description\": \"Bộ từ KÍNH TRỌNG, dùng khi hỏi hoặc nhắc tới người nhà của người khác. Dễ nhận ra vì luôn có お ở đầu và さん ở cuối: おとうさん, おかあさん. Đây cũng là cách trẻ con Nhật gọi bố mẹ mình.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(74,9,'N5','Bài 3: Người xung quanh',3,'NORMAL','{\"expReward\": 20, \"description\": \"Từ vựng gọi người theo vai trò xã hội. Lưu ý ひと (người) là từ trung tính, còn かた là cách gọi lịch sự hơn, dùng khi nói về người trên hoặc khách.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(75,9,'N5','Bài 4: Gia đình bạn có mấy người?',4,'NORMAL','{\"expReward\": 20, \"description\": \"Đếm người dùng đuôi にん, nhưng 1 người và 2 người bất quy tắc: ひとり, ふたり. Từ 3 người trở đi mới đều: さんにん, よにん, ごにん.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(76,9,'N5','Bài 5: Giới thiệu gia đình',5,'NORMAL','{\"expReward\": 20, \"description\": \"Bài tổng hợp: ghép từ vựng gia đình với nghề nghiệp, tuổi tác và động từ います thành một đoạn giới thiệu hoàn chỉnh — đúng dạng câu hỏi thường gặp nhất trong kỳ thi nói JLPT và phỏng vấn.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(77,9,'N5','Ôn tập: Gia đình và con người',6,'TOPIC_REVIEW','{\"expReward\": 30, \"description\": \"\", \"replayExpRatio\": 0.3, \"starThresholds\": [90, 150], \"entryCostEnergy\": 5, \"questionsPerSession\": 12}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(78,9,'N5','Ôn tập tốc độ: Gia đình và con người',NULL,'TIMED_REVIEW','{\"expReward\": 30, \"description\": \"\", \"replayExpRatio\": 0.3, \"starThresholds\": [90, 150], \"entryCostEnergy\": 5, \"questionsPerSession\": 12}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(79,9,'N5','Thi vượt: Gia đình và con người',NULL,'JUMP_TEST','{\"expReward\": 80, \"description\": \"\", \"entryCostEnergy\": 15, \"questionsPerSession\": 15}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(80,10,'N5','Bài 1: Tính từ đuôi い',1,'NORMAL','{\"expReward\": 20, \"description\": \"Nhóm tính từ kết thúc bằng chữ い, đứng trực tiếp trước danh từ mà không cần thêm gì: たかいほん (quyển sách đắt). Đây là nhóm đông đảo nhất.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(81,10,'N5','Bài 2: Tính từ đuôi な',2,'NORMAL','{\"expReward\": 20, \"description\": \"Nhóm này phải THÊM な khi đứng trước danh từ: きれいなはな (bông hoa đẹp), nhưng khi đứng cuối câu thì bỏ な: このはなはきれいです. Bẫy thường gặp: きれい và ゆうめい tuy kết thúc bằng い nhưng vẫn là tính từ な.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(82,10,'N5','Bài 3: Màu sắc',3,'NORMAL','{\"expReward\": 20, \"description\": \"4 màu cơ bản あかい, あおい, しろい, くろい là tính từ đuôi い. Nhưng các màu còn lại như みどり, ちゃいろ lại là danh từ, phải thêm の khi bổ nghĩa: みどりのくるま (chiếc xe màu xanh lá).\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(83,10,'N5','Bài 4: Thời tiết và bốn mùa',4,'NORMAL','{\"expReward\": 20, \"description\": \"Nhật Bản có 4 mùa rõ rệt và người Nhật rất hay mở đầu câu chuyện bằng chuyện thời tiết — giống như người Việt hỏi ăn cơm chưa. きょうはあついですね là câu bắt chuyện an toàn nhất.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(84,10,'N5','Bài 5: Phủ định tính từ',5,'NORMAL','{\"expReward\": 20, \"description\": \"2 loại tính từ phủ định khác nhau: tính từ い bỏ い thêm くない (たかい → たかくないです), tính từ な thì thêm じゃありません (しずか → しずかじゃありません). Ngoại lệ duy nhất: いい → よくないです.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(85,10,'N5','Bài 6: Nối hai tính từ',6,'NORMAL','{\"expReward\": 20, \"description\": \"Muốn khen 2 điều cùng lúc: tính từ い đổi い thành くて (やすくて おいしい = rẻ mà ngon), tính từ な thì thêm で (しずかで きれい). Đây là mẫu câu ghi điểm trong phần thi nói vì cho thấy bạn diễn đạt được ý phức tạp.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(86,10,'N5','Ôn tập: Tính từ và miêu tả',7,'TOPIC_REVIEW','{\"expReward\": 30, \"description\": \"\", \"replayExpRatio\": 0.3, \"starThresholds\": [90, 150], \"entryCostEnergy\": 5, \"questionsPerSession\": 12}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(87,10,'N5','Ôn tập tốc độ: Tính từ và miêu tả',NULL,'TIMED_REVIEW','{\"expReward\": 30, \"description\": \"\", \"replayExpRatio\": 0.3, \"starThresholds\": [90, 150], \"entryCostEnergy\": 5, \"questionsPerSession\": 12}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(88,10,'N5','Thi vượt: Tính từ và miêu tả',NULL,'JUMP_TEST','{\"expReward\": 80, \"description\": \"\", \"entryCostEnergy\": 15, \"questionsPerSession\": 15}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(89,11,'N5','Bài 1: Các loại cửa hàng',1,'NORMAL','{\"expReward\": 20, \"description\": \"Tiếng Nhật đặt tên cửa hàng cực kỳ dễ đoán: lấy tên món hàng rồi thêm や (ya) vào sau. ほん (sách) → ほんや (hiệu sách), にく (thịt) → にくや (hàng thịt), パン (bánh mì) → パンや (tiệm bánh). Biết mẹo này là tự đoán được tên hàng chục cửa hàng mà không cần học thuộc từng từ.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(90,11,'N5','Bài 2: Quần áo và đồ mặc',2,'NORMAL','{\"expReward\": 20, \"description\": \"Phần lớn tên quần áo trong tiếng Nhật là từ mượn tiếng Anh viết bằng Katakana, đọc lên là đoán ra ngay: シャツ (shirt), コート (coat), スカート (skirt). Riêng ふく (quần áo nói chung), くつ (giày) và ぼうし (mũ) là từ thuần Nhật, phải nhớ riêng.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(91,11,'N5','Bài 3: Hỏi giá và trả tiền',3,'NORMAL','{\"expReward\": 20, \"description\": \"いくらですか là câu bạn sẽ nói nhiều nhất khi mua sắm. Ở quầy thu ngân レジ, nhân viên hầu như luôn hỏi hai câu: có cần túi không (ふくろ) và trả bằng tiền mặt hay thẻ — げんきん hay カード, hai từ bạn đã học ở chủ đề nhà hàng.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(92,11,'N5','Bài 4: Chọn cỡ và màu',4,'NORMAL','{\"expReward\": 20, \"description\": \"サイズ mượn thẳng từ size tiếng Anh. Muốn xin cỡ khác chỉ cần ghép tính từ đã học ở chủ đề miêu tả với サイズ: おおきいサイズ (cỡ lớn hơn), ちいさいサイズ (cỡ nhỏ hơn), rồi thêm はありますか (có … không ạ?).\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(93,11,'N5','Bài 5: Giảm giá và khuyến mãi',5,'NORMAL','{\"expReward\": 20, \"description\": \"Ở Nhật bảng giá dán chữ はんがく nghĩa là còn một nửa, còn むりょう là miễn phí — hai chữ đáng để nhận mặt sớm. セール thì mượn từ sale, thấy ở cửa kính mọi cửa hàng vào tháng 1 và tháng 7 hằng năm.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(94,11,'N5','Bài 6: Hội thoại mua hàng trọn vẹn',6,'NORMAL','{\"expReward\": 20, \"description\": \"Ghép tất cả lại thành một lần mua hàng thật: xin xem đồ (みせてください), hỏi giá, chốt mua (これにします) hoặc từ chối lịch sự (けっこうです). けっこうです rất dễ hiểu nhầm — nó nghĩa là thôi, không cần đâu ạ, chứ không phải đồng ý.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(95,11,'N5','Ôn tập: Mua sắm ở cửa hàng',7,'TOPIC_REVIEW','{\"expReward\": 30, \"description\": \"\", \"replayExpRatio\": 0.3, \"starThresholds\": [90, 150], \"entryCostEnergy\": 5, \"questionsPerSession\": 12}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(96,11,'N5','Ôn tập tốc độ: Mua sắm ở cửa hàng',NULL,'TIMED_REVIEW','{\"expReward\": 30, \"description\": \"\", \"replayExpRatio\": 0.3, \"starThresholds\": [90, 150], \"entryCostEnergy\": 5, \"questionsPerSession\": 12}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(97,11,'N5','Thi vượt: Mua sắm ở cửa hàng',NULL,'JUMP_TEST','{\"expReward\": 80, \"description\": \"\", \"entryCostEnergy\": 15, \"questionsPerSession\": 15}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(98,12,'N5','Bài 1: Phương tiện đi lại',1,'NORMAL','{\"expReward\": 20, \"description\": \"Nhóm từ này chia làm hai: từ thuần Nhật (でんしゃ tàu điện, くるま ô tô, じてんしゃ xe đạp, ひこうき máy bay) và từ mượn viết Katakana (バス, タクシー). しんかんせん là tàu siêu tốc — chữ này ghép từ 3 phần nghĩa đen là tuyến đường ray mới.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(99,12,'N5','Bài 2: Ở nhà ga',2,'NORMAL','{\"expReward\": 20, \"description\": \"Ga tàu Nhật rất lớn, biết 4 chữ này là không lạc: きっぷ (vé), かいさつ (cửa soát vé), ホーム (sân ga, mượn từ platform), でぐち (lối ra). Bảng chỉ dẫn trong ga hầu như chỗ nào cũng có 4 chữ đó.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(100,12,'N5','Bài 3: Lên xe, xuống xe',3,'NORMAL','{\"expReward\": 20, \"description\": \"Chú ý trợ từ: lên xe dùng に (でんしゃにのります), còn đi bằng phương tiện gì thì dùng で (でんしゃでいきます). Người Việt hay lẫn hai câu này. Riêng đi bộ thì không dùng で mà nói あるいて.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(101,12,'N5','Bài 4: Hỏi đường',4,'NORMAL','{\"expReward\": 20, \"description\": \"Bạn đã biết まっすぐ và みぎにまがって ở chủ đề vị trí. Bài này thêm các mốc người Nhật hay lấy làm chuẩn khi chỉ đường: しんごう (đèn giao thông), こうさてん (ngã tư), かど (góc phố), はし (cây cầu).\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(102,12,'N5','Bài 5: Đi mất bao lâu',5,'NORMAL','{\"expReward\": 20, \"description\": \"Mẫu 〜から〜まで…かかります là cách chuẩn để nói quãng đường mất bao lâu: うちからえきまでじゅっぷんかかります = từ nhà đến ga mất 10 phút. どのくらい là câu hỏi tương ứng: khoảng bao lâu.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(103,12,'N5','Bài 6: Khi tàu trễ, tàu đông',6,'NORMAL','{\"expReward\": 20, \"description\": \"Tàu Nhật hiếm khi trễ, nhưng khi trễ thì loa ga báo bằng chữ おくれて います. Giờ cao điểm sáng thì tàu こんでいます (đông nghẹt) — hai chữ này nghe được là bớt hoang mang hẳn.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(104,12,'N5','Ôn tập: Đi lại và phương tiện',7,'TOPIC_REVIEW','{\"expReward\": 30, \"description\": \"\", \"replayExpRatio\": 0.3, \"starThresholds\": [90, 150], \"entryCostEnergy\": 5, \"questionsPerSession\": 12}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(105,12,'N5','Ôn tập tốc độ: Đi lại và phương tiện',NULL,'TIMED_REVIEW','{\"expReward\": 30, \"description\": \"\", \"replayExpRatio\": 0.3, \"starThresholds\": [90, 150], \"entryCostEnergy\": 5, \"questionsPerSession\": 12}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(106,12,'N5','Thi vượt: Đi lại và phương tiện',NULL,'JUMP_TEST','{\"expReward\": 80, \"description\": \"\", \"entryCostEnergy\": 15, \"questionsPerSession\": 15}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(107,13,'N5','Bài 1: Sở thích của tôi',1,'NORMAL','{\"expReward\": 20, \"description\": \"Mẫu câu しゅみは〜です dùng đúng một lần là dùng được cả đời: わたしのしゅみは りょうりです (sở thích của tôi là nấu ăn). Chỗ trống điền một danh từ chỉ hoạt động, không phải động từ.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(108,13,'N5','Bài 2: Thể thao',2,'NORMAL','{\"expReward\": 20, \"description\": \"Tên môn thể thao đi với động từ します (chơi, làm): サッカーをします = chơi bóng đá. Đừng dịch chơi thành あそびます — あそびます chỉ dùng cho chơi đùa nói chung, không dùng cho môn thể thao.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(109,13,'N5','Bài 3: Phim ảnh và âm nhạc',3,'NORMAL','{\"expReward\": 20, \"description\": \"Ba động từ đi kèm khác nhau, nhớ đúng cặp thì câu mới tự nhiên: えいがを みます (xem phim), おんがくをききます (nghe nhạc), うたをうたいます (hát bài hát). Cụm cuối lặp gốc từ うた nghe hơi lạ nhưng người Nhật nói đúng như vậy.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(110,13,'N5','Bài 4: Thích và không thích',4,'NORMAL','{\"expReward\": 20, \"description\": \"Điểm dễ sai nhất: thứ được thích đi với が chứ không phải を — すしがすきです, không nói すしをすきです. Lý do là すき không phải động từ mà là tính từ な, nên câu có nghĩa đen gần với sushi thì đáng thích đối với tôi.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(111,13,'N5','Bài 5: Giỏi và kém',5,'NORMAL','{\"expReward\": 20, \"description\": \"じょうず và へた cũng đi với が như すき. Một lưu ý về văn hoá: người Nhật gần như không tự khen mình じょうず — nói về bản thân thì họ dùng すき hoặc とくい, còn じょうず để dành khen người khác.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(112,13,'N5','Bài 6: Cuối tuần bạn làm gì',6,'NORMAL','{\"expReward\": 20, \"description\": \"Bốn trạng từ tần suất này đặt ngay trước động từ: いつも (luôn luôn) > よく (thường xuyên) > ときどき (thỉnh thoảng) > ぜんぜん (hoàn toàn không). Riêng ぜんぜん bắt buộc đi với đuôi phủ định ở cuối câu.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(113,13,'N5','Ôn tập: Sở thích và ngày nghỉ',7,'TOPIC_REVIEW','{\"expReward\": 30, \"description\": \"\", \"replayExpRatio\": 0.3, \"starThresholds\": [90, 150], \"entryCostEnergy\": 5, \"questionsPerSession\": 12}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(114,13,'N5','Ôn tập tốc độ: Sở thích và ngày nghỉ',NULL,'TIMED_REVIEW','{\"expReward\": 30, \"description\": \"\", \"replayExpRatio\": 0.3, \"starThresholds\": [90, 150], \"entryCostEnergy\": 5, \"questionsPerSession\": 12}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(115,13,'N5','Thi vượt: Sở thích và ngày nghỉ',NULL,'JUMP_TEST','{\"expReward\": 80, \"description\": \"\", \"entryCostEnergy\": 15, \"questionsPerSession\": 15}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(116,14,'N5','Bài 1: Các bộ phận cơ thể',1,'NORMAL','{\"expReward\": 20, \"description\": \"Toàn từ ngắn một đến hai âm, rất dễ nhớ nhưng cũng rất dễ lẫn vì có nhiều từ đồng âm: め là mắt, みみ là tai, はな ở đây là mũi (trùng âm với はな hoa). Trong câu, ngữ cảnh sẽ cho biết đang nói đến nghĩa nào.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(117,14,'N5','Bài 2: Nói chỗ đang đau',2,'NORMAL','{\"expReward\": 20, \"description\": \"Công thức đúng một mẫu duy nhất, thay tên bộ phận vào là xong: 〜がいたいです. あたまがいたいです = tôi đau đầu. Chú ý dùng が chứ không dùng は, vì phần đứng trước が chính là chỗ đang có vấn đề.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(118,14,'N5','Bài 3: Bệnh viện và thuốc',3,'NORMAL','{\"expReward\": 20, \"description\": \"Ở Nhật thuốc kê đơn lấy tại くすりや ngay cạnh bệnh viện, còn thuốc thường mua ở siêu thị thuốc. Động từ đi với thuốc là のみます (uống) — kể cả thuốc viên hay thuốc bột đều dùng のみます.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(119,14,'N5','Bài 4: Cảm giác trong người',4,'NORMAL','{\"expReward\": 20, \"description\": \"つかれました đã ở thể quá khứ sẵn — người Nhật nói tôi đã mệt chứ không nói tôi đang mệt, vì mệt là kết quả của việc vừa làm xong. Đây là câu bạn sẽ nghe đồng nghiệp nói mỗi chiều tan làm.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(120,14,'N5','Bài 5: Lời khuyên và lời chúc',5,'NORMAL','{\"expReward\": 20, \"description\": \"おだいじに là câu chia tay chuẩn mực khi người kia đang ốm, dịch thoáng là giữ gìn sức khoẻ nhé. Nói câu này lúc bạn bè hay đồng nghiệp Nhật xin nghỉ ốm sẽ được đánh giá là rất tinh ý.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(121,14,'N5','Bài 6: Ở phòng khám',6,'NORMAL','{\"expReward\": 20, \"description\": \"Bác sĩ Nhật gần như luôn mở đầu bằng どうしましたか (bạn bị làm sao?) rồi hỏi いつからですか (từ khi nào?). Chỉ cần trả lời được hai câu đó là buổi khám trôi qua được, phần còn lại bác sĩ sẽ dẫn.\", \"replayExpRatio\": 0.3, \"entryCostEnergy\": 10, \"questionsPerSession\": 10}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(122,14,'N5','Ôn tập: Sức khoẻ và cơ thể',7,'TOPIC_REVIEW','{\"expReward\": 30, \"description\": \"\", \"replayExpRatio\": 0.3, \"starThresholds\": [90, 150], \"entryCostEnergy\": 5, \"questionsPerSession\": 12}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(123,14,'N5','Ôn tập tốc độ: Sức khoẻ và cơ thể',NULL,'TIMED_REVIEW','{\"expReward\": 30, \"description\": \"\", \"replayExpRatio\": 0.3, \"starThresholds\": [90, 150], \"entryCostEnergy\": 5, \"questionsPerSession\": 12}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL),(124,14,'N5','Thi vượt: Sức khoẻ và cơ thể',NULL,'JUMP_TEST','{\"expReward\": 80, \"description\": \"\", \"entryCostEnergy\": 15, \"questionsPerSession\": 15}','2026-08-26 17:38:14','2026-08-26 17:38:14',NULL);
