/*!40000 ALTER TABLE `lesson_questions` DISABLE KEYS */;
INSERT INTO `lesson_questions` VALUES (1,1,'TRANSLATE_TO_VN','「おはよう」 (ohayou) nghĩa là gì?',NULL,NULL,'{\"vn\": \"chào buổi sáng\", \"kana\": \"おはよう\", \"romaji\": \"ohayou\", \"glossary\": {\"おはよう\": {\"r\": \"ohayou\", \"v\": \"chào buổi sáng\"}}, \"teachAudio\": \"/uploads/audios/words/ohayou.mp3\"}','2026-08-26 17:38:14','2026-08-26 17:38:14'),(2,1,'LISTEN_AND_SELECT','Nghe và chọn từ tiếng Nhật đúng','/uploads/audios/words/ohayou.mp3',NULL,'{\"vn\": \"chào buổi sáng\", \"romaji\": \"ohayou\", \"glossary\": {\"あさ\": {\"r\": \"asa\", \"v\": \"buổi sáng\"}, \"おはよう\": {\"r\": \"ohayou\", \"v\": \"chào buổi sáng\"}, \"ありがとう\": {\"r\": \"arigatou\", \"v\": \"cảm ơn\"}, \"すみません\": {\"r\": \"sumimasen\", \"v\": \"xin lỗi / cho hỏi\"}}}','2026-08-26 17:38:14','2026-08-26 17:38:14'),(3,1,'TRANSLATE_TO_VN','「こんにちは」 (konnichiwa) nghĩa là gì?',NULL,NULL,'{\"vn\": \"xin chào (ban ngày)\", \"kana\": \"こんにちは\", \"romaji\": \"konnichiwa\", \"glossary\": {\"こんにちは\": {\"r\": \"konnichiwa\", \"v\": \"xin chào (ban ngày)\"}}, \"teachAudio\": \"/uploads/audios/words/konnichiwa.mp3\"}','2026-08-26 17:38:14','2026-08-26 17:38:14'),(4,1,'LISTEN_AND_SELECT','Nghe và chọn từ tiếng Nhật đúng','/uploads/audios/words/konnichiwa.mp3',NULL,'{\"vn\": \"xin chào (ban ngày)\", \"romaji\": \"konnichiwa\", \"glossary\": {\"あさ\": {\"r\": \"asa\", \"v\": \"buổi sáng\"}, \"どうも\": {\"r\": \"doumo\", \"v\": \"rất / xin chào\"}, \"こんにちは\": {\"r\": \"konnichiwa\", \"v\": \"xin chào (ban ngày)\"}, \"だいじょうぶ\": {\"r\": \"daijoubu\", \"v\": \"không sao, ổn\"}}}','2026-08-26 17:38:14','2026-08-26 17:38:14'),(5,1,'TRANSLATE_TO_VN','「こんばんは」 (konbanwa) nghĩa là gì?',NULL,NULL,'{\"vn\": \"chào buổi tối\", \"kana\": \"こんばんは\", \"romaji\": \"konbanwa\", \"glossary\": {\"こんばんは\": {\"r\": \"konbanwa\", \"v\": \"chào buổi tối\"}}, \"teachAudio\": \"/uploads/audios/words/konbanwa.mp3\"}','2026-08-26 17:38:14','2026-08-26 17:38:14'),(6,1,'LISTEN_AND_SELECT','Nghe và chọn từ tiếng Nhật đúng','/uploads/audios/words/konbanwa.mp3',NULL,'{\"vn\": \"chào buổi tối\", \"romaji\": \"konbanwa\", \"glossary\": {\"おはよう\": {\"r\": \"ohayou\", \"v\": \"chào buổi sáng\"}, \"おやすみ\": {\"r\": \"oyasumi\", \"v\": \"chúc ngủ ngon\"}, \"ありがとう\": {\"r\": \"arigatou\", \"v\": \"cảm ơn\"}, \"こんばんは\": {\"r\": \"konbanwa\", \"v\": \"chào buổi tối\"}}}','2026-08-26 17:38:14','2026-08-26 17:38:14'),(7,1,'TRANSLATE_TO_VN','「おやすみ」 (oyasumi) nghĩa là gì?',NULL,NULL,'{\"vn\": \"chúc ngủ ngon\", \"kana\": \"おやすみ\", \"romaji\": \"oyasumi\", \"glossary\": {\"おやすみ\": {\"r\": \"oyasumi\", \"v\": \"chúc ngủ ngon\"}}, \"teachAudio\": \"/uploads/audios/words/oyasumi.mp3\"}','2026-08-26 17:38:14','2026-08-26 17:38:14'),(8,1,'LISTEN_AND_SELECT','Nghe và chọn từ tiếng Nhật đúng','/uploads/audios/words/oyasumi.mp3',NULL,'{\"vn\": \"chúc ngủ ngon\", \"romaji\": \"oyasumi\", \"glossary\": {\"どうも\": {\"r\": \"doumo\", \"v\": \"rất / xin chào\"}, \"おはよう\": {\"r\": \"ohayou\", \"v\": \"chào buổi sáng\"}, \"おやすみ\": {\"r\": \"oyasumi\", \"v\": \"chúc ngủ ngon\"}, \"すみません\": {\"r\": \"sumimasen\", \"v\": \"xin lỗi / cho hỏi\"}}}','2026-08-26 17:38:14','2026-08-26 17:38:14'),(9,1,'TRANSLATE_TO_VN','「あさ」 (asa) nghĩa là gì?',NULL,NULL,'{\"vn\": \"buổi sáng\", \"kana\": \"あさ\", \"romaji\": \"asa\", \"glossary\": {\"あさ\": {\"r\": \"asa\", \"v\": \"buổi sáng\"}}, \"teachAudio\": \"/uploads/audios/words/asa.mp3\"}','2026-08-26 17:38:14','2026-08-26 17:38:14'),(10,1,'LISTEN_AND_SELECT','Nghe và chọn từ tiếng Nhật đúng','/uploads/audios/words/asa.mp3',NULL,'{\"vn\": \"buổi sáng\", \"romaji\": \"asa\", \"glossary\": {\"あさ\": {\"r\": \"asa\", \"v\": \"buổi sáng\"}, \"ごめん\": {\"r\": \"gomen\", \"v\": \"xin lỗi (thân mật)\"}, \"どうも\": {\"r\": \"doumo\", \"v\": \"rất / xin chào\"}, \"おはよう\": {\"r\": \"ohayou\", \"v\": \"chào buổi sáng\"}}}','2026-08-26 17:38:14','2026-08-26 17:38:14'),(11,1,'LISTEN_AND_ARRANGE','Nghe và sắp xếp thành câu hoàn chỉnh: Chào buổi sáng ạ, thưa thầy.','/uploads/audios/sentences/sensei-ohayou-gozaimasu.mp3','/uploads/i